CREATE TABLE notifications (id SERIAL PRIMARY KEY, recipient_id INTEGER, recipient_email VARCHAR(255), notification_type VARCHAR(100), subject VARCHAR(255), message TEXT, status VARCHAR(50), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, sent_at TIMESTAMPTZ);
CREATE TABLE email_queue (id SERIAL PRIMARY KEY, notification_id INTEGER REFERENCES notifications(id), to_email VARCHAR(255), from_email VARCHAR(255), subject VARCHAR(255), html_body TEXT, text_body TEXT, status VARCHAR(50), retry_count INTEGER DEFAULT 0, last_retry TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sms_queue (id SERIAL PRIMARY KEY, notification_id INTEGER REFERENCES notifications(id), to_phone VARCHAR(50), message TEXT, status VARCHAR(50), retry_count INTEGER DEFAULT 0, provider VARCHAR(100), sms_id VARCHAR(100), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE whatsapp_queue (id SERIAL PRIMARY KEY, notification_id INTEGER REFERENCES notifications(id), to_phone VARCHAR(50), message_type VARCHAR(50), message_content TEXT, media_url VARCHAR(500), status VARCHAR(50), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_templates (id SERIAL PRIMARY KEY, template_name VARCHAR(255), template_type VARCHAR(100), subject_template TEXT, body_template TEXT, variables TEXT[], created_at TIMESTAMPTZ);
CREATE TABLE notification_log (id SERIAL PRIMARY KEY, notification_id INTEGER, recipient_email VARCHAR(255), notification_type VARCHAR(100), delivery_status VARCHAR(50), error_message TEXT, delivered_at TIMESTAMPTZ);
